import { PrismaClient } from "@prisma/client";
// Explanation

// This imports the PrismaClient class from the @prisma/client package.

// @prisma/client is the package generated by Prisma after running:
// npx prisma generate
// PrismaClient is the main object used to communicate with your database.

// Think of it like this:

// Application
//       │
//       ▼
//  Prisma Client
//       │
//       ▼
//  Database

// Without importing PrismaClient, your application cannot perform database operations such as:

// Creating records
// Reading data
// Updating records
// Deleting records
const prisma = new PrismaClient({
  log: ["error", "warn"],
});
// Explanation

// This creates a new Prisma client instance.

// new PrismaClient() establishes the object your application will use to interact with the database.

// Example:

// await prisma.user.findMany();

// Here:

// prisma is the object.
// user is a model defined in your Prisma schema.
// findMany() fetches all users.
// Line 3
// log: ["error", "warn"],
// Explanation

// This configures Prisma's logging.

// It tells Prisma to display only:

// "error" → Database errors.
// "warn" → Warning messages.

// It intentionally hides "query" logs to avoid clutter.

// If you used:

// log: ["query"]

// you would see every SQL query executed, which is useful for debugging.
/**
 * @desc Connect DB
 */
export const connectDB = async () => {
  try {
    await prisma.$connect();
    console.log("✅ Database connected");
  } catch (err) {
    console.error("❌ Database connection failed", err.message);
    process.exit(1);
  }
};
// export makes the function available to other files.
// const connectDB defines the function.
// async allows the use of await inside the function.
export default prisma;